#pragma once
#include <shobjidl.h>
#include "related_locations.h"
std::vector<fs::path> relatedFiles(const Entry&e){std::vector<fs::path> paths{fs::path(e.path)};std::error_code ec;bool directory=fs::is_directory(e.path,ec);std::set<std::wstring> seen{lower(e.path)};auto add=[&](const fs::path&p){if(fs::exists(p,ec)&&deletionPathAllowed(p)&&seen.insert(lower(p.wstring())).second&&!inside(p.wstring(),e.path))paths.push_back(p);ec.clear();};
 size_t pos=0;while((pos=e.cache.find(L"[已知规则] ",pos))!=std::wstring::npos){pos+=7;auto end=e.cache.find(L" | ",pos);add(e.cache.substr(pos,end==std::wstring::npos?end:end-pos));if(end==std::wstring::npos)break;pos=end;}
 for(const auto& candidate:relatedDataLocations(e))add(candidate);
 for(int location:{CSIDL_DESKTOPDIRECTORY,CSIDL_COMMON_DESKTOPDIRECTORY,CSIDL_PROGRAMS,CSIDL_COMMON_PROGRAMS}){wchar_t base[MAX_PATH];if(FAILED(SHGetFolderPathW(nullptr,location,nullptr,SHGFP_TYPE_CURRENT,base)))continue;std::vector<fs::path> dirs{base};int count=0;while(!dirs.empty()&&count<5000){auto dir=dirs.back();dirs.pop_back();fs::directory_iterator it(dir,ec),end;if(ec){ec.clear();continue;}for(;it!=end;it.increment(ec)){if(ec){ec.clear();break;}if(++count>5000)break;auto path=it->path();DWORD a=GetFileAttributesW(path.c_str());if(a==INVALID_FILE_ATTRIBUTES||a&FILE_ATTRIBUTE_REPARSE_POINT)continue;if(a&FILE_ATTRIBUTE_DIRECTORY){dirs.push_back(path);continue;}if(lower(path.extension().wstring())!=L".lnk")continue;IShellLinkW* link=nullptr;if(SUCCEEDED(CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&link)))){IPersistFile* file=nullptr;if(SUCCEEDED(link->QueryInterface(IID_PPV_ARGS(&file)))){if(SUCCEEDED(file->Load(path.c_str(),STGM_READ))){wchar_t target[32768];WIN32_FIND_DATAW data{};if(SUCCEEDED(link->GetPath(target,32768,&data,SLGP_RAWPATH))&&inside(target,e.path))add(path);}file->Release();}link->Release();}}}}
 return paths;}
struct UninstallerCommand{std::wstring executable,arguments;};
UninstallerCommand parseUninstaller(std::wstring command){UninstallerCommand result;size_t first=command.find_first_not_of(L" \t");if(first==std::wstring::npos)return result;command.erase(0,first);size_t end;if(command.front()==L'"'){end=command.find(L'"',1);if(end==std::wstring::npos)return {};result.executable=command.substr(1,end-1);end++;}else{auto extension=lower(command).find(L".exe");if(extension==std::wstring::npos)return {};end=extension+4;result.executable=command.substr(0,end);}result.arguments=command.substr(end);if(lower(fs::path(result.executable).extension().wstring())!=L".exe")return {};return result;}
#include "uninstaller_wait.h"
bool runUninstaller(const std::wstring& command){if(command.empty())return true;auto parsed=parseUninstaller(command);if(parsed.executable.empty()){deleteDialog(nullptr,L"卸载命令格式无法安全识别。未继续删除文件，请先使用 Windows 卸载功能。",L"无法完整卸载",MB_OK|MB_ICONWARNING);return false;}DWORD code=1;if(!waitForUninstaller(parsed.executable,parsed.arguments,code)){deleteDialog(nullptr,L"未能启动或完整监控官方卸载程序。未继续删除文件。",L"卸载未完成",MB_OK|MB_ICONWARNING);return false;}if(code!=0){auto text=L"官方卸载程序返回代码 "+std::to_wstring(code)+L"。可能已取消、需要重启或遇到错误。未继续清理文件，请先确认卸载结果。";deleteDialog(nullptr,text.c_str(),L"卸载未确认成功",MB_OK|MB_ICONWARNING);return false;}return deleteDialog(nullptr,L"请确认官方卸载程序显示卸载成功，且后续确认窗口和进度窗口均已结束。\n\n若仍在卸载、已取消或提示重启，请选择“否”，应用将保留在列表。\n选择“是”后继续清理残留；清理成功并点击最终结果的“确定”后才播放消失特效。",L"官方卸载是否已完成？",MB_YESNO|MB_DEFBUTTON2|MB_ICONQUESTION)==IDYES;}
